def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in (2, 3, 4, 6):
                # Replace anomalous marker cells inside the large 1-region;
                # otherwise restore the background.
                out[r][c] = 1 if any(
                    0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 1
                    for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                ) else 0
    return out
